-- Histórias (quadrinhos 4-6 e 7-10, dilema 11-13) dos devocionais de 01 a 04/11, em pt-BR, en, es, fr e it.
-- Devocionais: Davi e a arca (01/11), Levi e o banquete (02/11), A mulher e o perfume (03/11), Marta e Maria (04/11).
-- As traduções são feitas por IA a partir do pt-BR. As falas de Jesus em Lucas são paráfrases; conferir com a Bíblia usada pelo editorial.
-- Só mexe no campo story; o texto corrido (what_it_says) não é tocado. A arte está em public/ilustracoes/<devocional>/quadros/ (publicar o app antes).
-- railway connect 3minutes-db < docs/plano-melhorias/kids-story-novembro.sql
-- Tudo ou nada: exige as 60 versões, publicadas e sem história; desfaz se qualquer UPDATE não atingir 1 linha.
-- Rollback: docs/plano-melhorias/kids-story-novembro-rollback.sql

\set ON_ERROR_STOP on
BEGIN;

DO $$
BEGIN
  IF (SELECT count(*) FROM devotional_kids WHERE devotional_id IN ('cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvyun7rw0032o72lmlzc68bk','cmvyv3ozp003ho72lezbf5h9r') AND language IN ('pt-BR','en','es','fr','it') AND band IN ('4-6','7-10','11-13') AND status = 'published' AND story IS NULL) <> 60 THEN
    RAISE EXCEPTION 'Esperava 60 versões publicadas e sem história; nada foi alterado.';
  END IF;
END $$;

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-1.svg", "caption": "Davi levou a arca de Deus para Jerusalém.", "speech": "Deus está com a gente!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-2.svg", "caption": "O povo tocava trombetas e gritava de alegria.", "speech": "Viva o Senhor!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-3.svg", "caption": "Davi dançou com todas as suas forças, mesmo sendo rei.", "speech": "Minha alegria é estar com Deus!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-1.svg", "caption": "Davi decidiu levar a arca para Jerusalém. Ela lembrava que Deus estava no meio do povo.", "speech": "Com cuidado e respeito."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-2.svg", "caption": "Deus é santo. Por isso, depois dos primeiros passos, Davi ofereceu sacrifícios ao Senhor.", "speech": "Ele merece todo o nosso respeito."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-3.svg", "caption": "Então houve festa! O povo gritava de alegria e Davi dançava com todas as suas forças.", "speech": "Que alegria estar perto de Deus!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-4.svg", "caption": "Mical viu tudo pela janela e achou uma vergonha para um rei. Para Davi, adorar valia mais que parecer importante.", "speech": "Eu danço para o Senhor!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '7-10' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/davi-e-a-arca/quadros/11-13-cena.svg", "setup": "Jerusalém. Você é Davi, o rei. A arca de Deus está chegando à cidade e todos esperam um cortejo sério e cheio de pose. Mas seu coração está transbordando de alegria, e sua esposa observa da janela.", "question": "O que você faria?", "options": ["Manter a pose de rei", "Dançar junto com o povo", "Esperar a festa acabar para celebrar sozinho"], "outcome": "Davi dançou diante do Senhor com todas as suas forças. Mical o viu pela janela e o desprezou no coração. Para Davi, a alegria de estar diante de Deus valia mais que a aparência de rei.", "outcomeQuestion": "Alguém mudaria a escolha de agora há pouco?", "today": "Hoje também é fácil se preocupar com o que os outros vão pensar, até na hora de agradecer a Deus. A adoração verdadeira olha para Deus, não para a plateia.", "todayQuestion": "O que você deixa de fazer por Deus por medo do que vão pensar?"}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '11-13' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-1.svg", "caption": "David took God's ark to Jerusalem.", "speech": "God is with us!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-2.svg", "caption": "The people played trumpets and shouted for joy.", "speech": "Hooray for the Lord!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-3.svg", "caption": "David danced with all his strength, even though he was king.", "speech": "My joy is being with God!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-1.svg", "caption": "David decided to bring the ark to Jerusalem. It reminded everyone that God was among his people.", "speech": "Carefully and with respect."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-2.svg", "caption": "God is holy. So after the first steps, David offered sacrifices to the Lord.", "speech": "He deserves all our respect."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-3.svg", "caption": "Then came the celebration! The people shouted for joy and David danced with all his strength.", "speech": "What joy to be near God!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-4.svg", "caption": "Michal saw it all from the window and thought it was shameful for a king. For David, worshiping mattered more than looking important.", "speech": "I dance for the Lord!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '7-10' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/davi-e-a-arca/quadros/11-13-cena.svg", "setup": "Jerusalem. You are David, the king. God's ark is arriving in the city, and everyone expects a serious, dignified procession. But your heart is overflowing with joy, and your wife is watching from the window.", "question": "What would you do?", "options": ["Keep up the royal appearance", "Dance along with the people", "Wait until the party is over and celebrate alone"], "outcome": "David danced before the Lord with all his strength. Michal saw him from the window and despised him in her heart. For David, the joy of being before God mattered more than looking like a king.", "outcomeQuestion": "Would anyone change the choice they made a moment ago?", "today": "Today it's just as easy to worry about what others will think, even when thanking God. True worship looks to God, not to the audience.", "todayQuestion": "What do you hold back from doing for God because of what people might think?"}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '11-13' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-1.svg", "caption": "David llevó el arca de Dios a Jerusalén.", "speech": "¡Dios está con nosotros!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-2.svg", "caption": "El pueblo tocaba trompetas y gritaba de alegría.", "speech": "¡Viva el Señor!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-3.svg", "caption": "David bailó con todas sus fuerzas, aunque era rey.", "speech": "¡Mi alegría es estar con Dios!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-1.svg", "caption": "David decidió llevar el arca a Jerusalén. Ella recordaba que Dios estaba en medio de su pueblo.", "speech": "Con cuidado y respeto."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-2.svg", "caption": "Dios es santo. Por eso, después de los primeros pasos, David ofreció sacrificios al Señor.", "speech": "Él merece todo nuestro respeto."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-3.svg", "caption": "¡Entonces hubo fiesta! El pueblo gritaba de alegría y David bailaba con todas sus fuerzas.", "speech": "¡Qué alegría estar cerca de Dios!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-4.svg", "caption": "Mical lo vio todo desde la ventana y pensó que era una vergüenza para un rey. Para David, adorar valía más que parecer importante.", "speech": "¡Yo bailo para el Señor!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '7-10' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/davi-e-a-arca/quadros/11-13-cena.svg", "setup": "Jerusalén. Eres David, el rey. El arca de Dios está llegando a la ciudad y todos esperan un cortejo serio y solemne. Pero tu corazón rebosa de alegría, y tu esposa te observa desde la ventana.", "question": "¿Qué harías?", "options": ["Mantener la postura de rey", "Bailar junto con el pueblo", "Esperar a que termine la fiesta y celebrar a solas"], "outcome": "David bailó delante del Señor con todas sus fuerzas. Mical lo vio desde la ventana y lo despreció en su corazón. Para David, la alegría de estar delante de Dios valía más que la apariencia de rey.", "outcomeQuestion": "¿Alguien cambiaría la elección de hace un momento?", "today": "Hoy también es fácil preocuparse por lo que otros pensarán, incluso a la hora de dar gracias a Dios. La verdadera adoración mira a Dios, no al público.", "todayQuestion": "¿Qué dejas de hacer por Dios por miedo a lo que digan?"}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '11-13' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-1.svg", "caption": "David a emporté l'arche de Dieu à Jérusalem.", "speech": "Dieu est avec nous !"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-2.svg", "caption": "Le peuple jouait de la trompette et criait de joie.", "speech": "Vive le Seigneur !"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-3.svg", "caption": "David a dansé de toutes ses forces, même s'il était roi.", "speech": "Ma joie, c'est d'être avec Dieu !"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-1.svg", "caption": "David a décidé d'amener l'arche à Jérusalem. Elle rappelait que Dieu était au milieu de son peuple.", "speech": "Avec soin et respect."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-2.svg", "caption": "Dieu est saint. Alors, après les premiers pas, David a offert des sacrifices au Seigneur.", "speech": "Il mérite tout notre respect."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-3.svg", "caption": "Puis ce fut la fête ! Le peuple criait de joie et David dansait de toutes ses forces.", "speech": "Quelle joie d'être près de Dieu !"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-4.svg", "caption": "Mical a tout vu par la fenêtre et a trouvé cela honteux pour un roi. Pour David, adorer comptait plus que paraître important.", "speech": "Je danse pour le Seigneur !"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '7-10' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/davi-e-a-arca/quadros/11-13-cena.svg", "setup": "Jérusalem. Tu es David, le roi. L'arche de Dieu arrive dans la ville et tout le monde attend un cortège sérieux et digne. Mais ton cœur déborde de joie, et ta femme t'observe depuis la fenêtre.", "question": "Que ferais-tu ?", "options": ["Garder la posture d'un roi", "Danser avec le peuple", "Attendre la fin de la fête pour célébrer seul"], "outcome": "David a dansé devant le Seigneur de toutes ses forces. Mical l'a vu par la fenêtre et l'a méprisé dans son cœur. Pour David, la joie d'être devant Dieu comptait plus que l'apparence d'un roi.", "outcomeQuestion": "Quelqu'un changerait-il le choix qu'il vient de faire ?", "today": "Aujourd'hui aussi, il est facile de s'inquiéter de ce que les autres vont penser, même au moment de remercier Dieu. La vraie adoration regarde vers Dieu, pas vers le public.", "todayQuestion": "Qu'est-ce que tu renonces à faire pour Dieu par peur du regard des autres ?"}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '11-13' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-1.svg", "caption": "Davide portò l'arca di Dio a Gerusalemme.", "speech": "Dio è con noi!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-2.svg", "caption": "Il popolo suonava le trombe e gridava di gioia.", "speech": "Viva il Signore!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/4-6-3.svg", "caption": "Davide danzò con tutte le sue forze, anche se era re.", "speech": "La mia gioia è stare con Dio!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-1.svg", "caption": "Davide decise di portare l'arca a Gerusalemme. Ricordava che Dio era in mezzo al suo popolo.", "speech": "Con cura e rispetto."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-2.svg", "caption": "Dio è santo. Perciò, dopo i primi passi, Davide offrì sacrifici al Signore.", "speech": "Merita tutto il nostro rispetto."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-3.svg", "caption": "Poi ci fu la festa! Il popolo gridava di gioia e Davide danzava con tutte le sue forze.", "speech": "Che gioia stare vicino a Dio!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/7-10-4.svg", "caption": "Mical vide tutto dalla finestra e pensò che fosse una vergogna per un re. Per Davide, adorare valeva più che sembrare importante.", "speech": "Io danzo per il Signore!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '7-10' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/davi-e-a-arca/quadros/11-13-cena.svg", "setup": "Gerusalemme. Sei Davide, il re. L'arca di Dio sta arrivando in città e tutti si aspettano un corteo serio e solenne. Ma il tuo cuore trabocca di gioia, e tua moglie ti osserva dalla finestra.", "question": "Che cosa faresti?", "options": ["Mantenere il contegno da re", "Danzare insieme al popolo", "Aspettare la fine della festa e celebrare da solo"], "outcome": "Davide danzò davanti al Signore con tutte le sue forze. Mical lo vide dalla finestra e lo disprezzò in cuor suo. Per Davide, la gioia di stare davanti a Dio valeva più dell'aspetto di un re.", "outcomeQuestion": "Qualcuno cambierebbe la scelta di poco fa?", "today": "Anche oggi è facile preoccuparsi di cosa penseranno gli altri, persino quando si ringrazia Dio. La vera adorazione guarda a Dio, non al pubblico.", "todayQuestion": "Che cosa tralasci di fare per Dio per paura di cosa penseranno?"}$j$::jsonb
 WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '11-13' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-1.svg", "caption": "Levi trabalhava cobrando impostos. Jesus o chamou, e Levi foi com ele.", "speech": "Siga-me!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-2.svg", "caption": "Levi fez uma grande refeição e convidou muita gente para comer com Jesus.", "speech": "Venham comer com a gente!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-3.svg", "caption": "Alguns religiosos reclamaram. Jesus explicou que veio chamar quem precisa de ajuda.", "speech": "Os doentes precisam de médico."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-1.svg", "caption": "Levi cobrava impostos para o governo. Um dia, Jesus o chamou para segui-lo.", "speech": "Siga-me."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-2.svg", "caption": "Levi se levantou, deixou tudo e foi com Jesus.", "speech": "Eu vou!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-3.svg", "caption": "Depois, Levi fez um grande banquete para honrar Jesus. Muita gente veio comer com eles.", "speech": "Venham, a mesa é de todos!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-4.svg", "caption": "Os religiosos reclamaram. Jesus disse que veio chamar pecadores a voltar para Deus e mudar de direção.", "speech": "Os doentes precisam de médico."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '7-10' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/levi-e-o-banquete/quadros/11-13-cena.svg", "setup": "Galileia. Você é um religioso respeitado. Um cobrador de impostos, que muita gente despreza, preparou uma grande refeição, e Jesus está à mesa. Seus amigos já estão reclamando.", "question": "O que você faria?", "options": ["Ficar de fora com os amigos", "Entrar e sentar à mesa", "Entrar, mas só para observar"], "outcome": "Jesus estava à mesa com quem mais sabia que precisava dele. Disse que veio chamar pecadores ao arrependimento: reconhecer o erro, voltar para Deus e mudar de direção. Quem reclamava também precisava de perdão.", "quote": "Não são os saudáveis que precisam de médico, e sim os doentes.", "outcomeQuestion": "Quem você costuma deixar de fora da sua mesa?", "today": "Hoje também é fácil julgar quem “não combina” com a gente. Na mesa de Jesus cabe quem reconhece que precisa dele, e isso inclui cada um de nós.", "todayQuestion": "Quem precisa de um convite seu esta semana?"}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '11-13' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-1.svg", "caption": "Levi worked collecting taxes. Jesus called him, and Levi went with him.", "speech": "Follow me!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-2.svg", "caption": "Levi prepared a big meal and invited many people to eat with Jesus.", "speech": "Come and eat with us!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-3.svg", "caption": "Some religious leaders complained. Jesus explained that he came to call those who need help.", "speech": "The sick need a doctor."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-1.svg", "caption": "Levi collected taxes for the government. One day, Jesus called him to follow.", "speech": "Follow me."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-2.svg", "caption": "Levi got up, left everything and went with Jesus.", "speech": "I'm coming!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-3.svg", "caption": "Later, Levi held a big banquet to honor Jesus. Many people came to eat with them.", "speech": "Come in, the table is for everyone!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-4.svg", "caption": "The religious leaders complained. Jesus said he came to call sinners to turn back to God and change direction.", "speech": "The sick need a doctor."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '7-10' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/levi-e-o-banquete/quadros/11-13-cena.svg", "setup": "Galilee. You are a respected religious leader. A tax collector, whom many people look down on, has prepared a big meal, and Jesus is at the table. Your friends are already complaining.", "question": "What would you do?", "options": ["Stay outside with my friends", "Go in and sit at the table", "Go in, but only to watch"], "outcome": "Jesus was at the table with those who knew best that they needed him. He said he came to call sinners to repentance: to admit wrong, turn back to God and change direction. Those who complained needed forgiveness too.", "quote": "It is not the healthy who need a doctor, but the sick.", "outcomeQuestion": "Who do you usually leave out of your table?", "today": "Today it's just as easy to judge those who “don't fit in” with us. At Jesus' table there is room for anyone who admits they need him, and that includes each one of us.", "todayQuestion": "Who needs an invitation from you this week?"}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '11-13' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-1.svg", "caption": "Leví trabajaba cobrando impuestos. Jesús lo llamó, y Leví fue con él.", "speech": "¡Sígueme!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-2.svg", "caption": "Leví preparó una gran comida e invitó a mucha gente a comer con Jesús.", "speech": "¡Vengan a comer con nosotros!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-3.svg", "caption": "Algunos religiosos se quejaron. Jesús explicó que vino a llamar a quienes necesitan ayuda.", "speech": "Los enfermos necesitan médico."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-1.svg", "caption": "Leví cobraba impuestos para el gobierno. Un día, Jesús lo llamó para que lo siguiera.", "speech": "Sígueme."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-2.svg", "caption": "Leví se levantó, lo dejó todo y fue con Jesús.", "speech": "¡Voy!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-3.svg", "caption": "Después, Leví hizo un gran banquete para honrar a Jesús. Mucha gente vino a comer con ellos.", "speech": "¡Pasen, la mesa es de todos!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-4.svg", "caption": "Los religiosos se quejaron. Jesús dijo que vino a llamar a los pecadores a volver a Dios y cambiar de rumbo.", "speech": "Los enfermos necesitan médico."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '7-10' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/levi-e-o-banquete/quadros/11-13-cena.svg", "setup": "Galilea. Eres un religioso respetado. Un cobrador de impuestos, a quien mucha gente desprecia, preparó una gran comida, y Jesús está a la mesa. Tus amigos ya se están quejando.", "question": "¿Qué harías?", "options": ["Quedarme afuera con mis amigos", "Entrar y sentarme a la mesa", "Entrar, pero solo para observar"], "outcome": "Jesús estaba a la mesa con quienes mejor sabían que lo necesitaban. Dijo que vino a llamar a los pecadores al arrepentimiento: reconocer el error, volver a Dios y cambiar de rumbo. Quienes se quejaban también necesitaban perdón.", "quote": "No son los sanos los que necesitan médico, sino los enfermos.", "outcomeQuestion": "¿A quién sueles dejar fuera de tu mesa?", "today": "Hoy también es fácil juzgar a quien “no encaja” con nosotros. En la mesa de Jesús cabe quien reconoce que lo necesita, y eso nos incluye a cada uno.", "todayQuestion": "¿Quién necesita una invitación tuya esta semana?"}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '11-13' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-1.svg", "caption": "Lévi travaillait à percevoir les impôts. Jésus l'a appelé, et Lévi l'a suivi.", "speech": "Suis-moi !"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-2.svg", "caption": "Lévi a préparé un grand repas et invité beaucoup de monde à manger avec Jésus.", "speech": "Venez manger avec nous !"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-3.svg", "caption": "Des religieux se sont plaints. Jésus a expliqué qu'il est venu appeler ceux qui ont besoin d'aide.", "speech": "Ce sont les malades qui ont besoin de médecin."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-1.svg", "caption": "Lévi percevait les impôts pour le gouvernement. Un jour, Jésus l'a appelé à le suivre.", "speech": "Suis-moi."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-2.svg", "caption": "Lévi s'est levé, a tout laissé et a suivi Jésus.", "speech": "J'arrive !"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-3.svg", "caption": "Ensuite, Lévi a donné un grand banquet en l'honneur de Jésus. Beaucoup de gens sont venus manger avec eux.", "speech": "Entrez, la table est à tout le monde !"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-4.svg", "caption": "Les religieux se sont plaints. Jésus a dit qu'il est venu appeler les pécheurs à revenir à Dieu et à changer de direction.", "speech": "Ce sont les malades qui ont besoin de médecin."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '7-10' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/levi-e-o-banquete/quadros/11-13-cena.svg", "setup": "La Galilée. Tu es un religieux respecté. Un collecteur d'impôts, méprisé par beaucoup, a préparé un grand repas, et Jésus est à table. Tes amis se plaignent déjà.", "question": "Que ferais-tu ?", "options": ["Rester dehors avec mes amis", "Entrer et m'asseoir à table", "Entrer, mais seulement pour observer"], "outcome": "Jésus était à table avec ceux qui savaient le mieux qu'ils avaient besoin de lui. Il a dit qu'il est venu appeler les pécheurs à la repentance : reconnaître son erreur, revenir à Dieu et changer de direction. Ceux qui se plaignaient avaient eux aussi besoin de pardon.", "quote": "Ce ne sont pas les bien-portants qui ont besoin de médecin, mais les malades.", "outcomeQuestion": "Qui laisses-tu habituellement à l'écart de ta table ?", "today": "Aujourd'hui encore, il est facile de juger ceux qui « ne nous ressemblent pas ». À la table de Jésus, il y a de la place pour celui qui reconnaît avoir besoin de lui, et cela nous inclut tous.", "todayQuestion": "Qui a besoin d'une invitation de ta part cette semaine ?"}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '11-13' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-1.svg", "caption": "Levi faceva l'esattore delle tasse. Gesù lo chiamò e Levi andò con lui.", "speech": "Seguimi!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-2.svg", "caption": "Levi preparò un grande pranzo e invitò molta gente a mangiare con Gesù.", "speech": "Venite a mangiare con noi!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/4-6-3.svg", "caption": "Alcuni religiosi si lamentarono. Gesù spiegò che era venuto a chiamare chi ha bisogno di aiuto.", "speech": "I malati hanno bisogno del medico."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-1.svg", "caption": "Levi riscuoteva le tasse per il governo. Un giorno, Gesù lo chiamò a seguirlo.", "speech": "Seguimi."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-2.svg", "caption": "Levi si alzò, lasciò tutto e andò con Gesù.", "speech": "Vengo!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-3.svg", "caption": "Poi Levi organizzò un grande banchetto in onore di Gesù. Molta gente venne a mangiare con loro.", "speech": "Entrate, la tavola è di tutti!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/7-10-4.svg", "caption": "I religiosi si lamentarono. Gesù disse che era venuto a chiamare i peccatori a tornare a Dio e a cambiare direzione.", "speech": "I malati hanno bisogno del medico."}]}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '7-10' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/levi-e-o-banquete/quadros/11-13-cena.svg", "setup": "Galilea. Sei un religioso rispettato. Un esattore delle tasse, disprezzato da molti, ha preparato un grande pranzo, e Gesù è a tavola. I tuoi amici si stanno già lamentando.", "question": "Che cosa faresti?", "options": ["Restare fuori con i miei amici", "Entrare e sedermi a tavola", "Entrare, ma solo per osservare"], "outcome": "Gesù era a tavola con chi sapeva meglio di avere bisogno di lui. Disse di essere venuto a chiamare i peccatori al pentimento: riconoscere l'errore, tornare a Dio e cambiare direzione. Anche chi si lamentava aveva bisogno di perdono.", "quote": "Non sono i sani che hanno bisogno del medico, ma i malati.", "outcomeQuestion": "Chi di solito lasci fuori dalla tua tavola?", "today": "Anche oggi è facile giudicare chi “non è dei nostri”. Alla tavola di Gesù c'è posto per chi riconosce di avere bisogno di lui, e questo include ciascuno di noi.", "todayQuestion": "Chi ha bisogno di un tuo invito questa settimana?"}$j$::jsonb
 WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '11-13' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-1.svg", "caption": "Jesus comia na casa de Simão. Uma mulher chegou trazendo um frasco de perfume.", "speech": "Quero agradecer a Jesus."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-2.svg", "caption": "Ela chorou, molhou os pés de Jesus com lágrimas e os enxugou com os cabelos.", "speech": "Obrigada, Jesus!"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-3.svg", "caption": "Jesus disse a ela que seus pecados estavam perdoados e que podia ir em paz.", "speech": "Que paz no coração!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-1.svg", "caption": "Durante uma refeição na casa de Simão, uma mulher se aproximou de Jesus chorando.", "speech": "Tenho tanto a agradecer."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-2.svg", "caption": "Ela molhou os pés dele com lágrimas, enxugou-os com os cabelos, beijou-os e colocou perfume.", "speech": "Obrigada por me perdoar."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-3.svg", "caption": "Simão julgava a mulher. Jesus contou de dois homens que deviam dinheiro, e o credor perdoou os dois.", "speech": "Qual dos dois vai amá-lo mais?"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-4.svg", "caption": "Quem recebe um perdão maior ama mais. Jesus disse à mulher que seus pecados estavam perdoados.", "speech": "Vá em paz."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '7-10' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/a-mulher-e-o-perfume/quadros/11-13-cena.svg", "setup": "A casa de Simão, um fariseu. Você é um dos convidados. Uma mulher conhecida na cidade como pecadora entra chorando e começa a cuidar dos pés de Jesus com lágrimas e perfume. Todos olham para você.", "question": "O que você pensaria?", "options": ["Esse não é lugar para ela", "Ela sabe o quanto precisa de perdão", "Eu também preciso ser perdoado"], "outcome": "Jesus conhecia os pensamentos de Simão e contou sobre dois devedores perdoados. Quem recebeu o perdão maior teria mais motivos para amar. Os gestos da mulher mostravam gratidão por um perdão recebido, e ela saiu em paz.", "quote": "Os seus pecados estão perdoados. Vá em paz.", "outcomeQuestion": "O que mudaria no seu olhar sobre ela?", "today": "Quem lembra o quanto foi perdoado costuma perdoar e acolher melhor. Quem se acha sem dívida tende a julgar.", "todayQuestion": "Quando foi a última vez que você agradeceu a Deus por ser perdoado?"}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '11-13' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-1.svg", "caption": "Jesus was eating at Simon's house. A woman came in bringing a jar of perfume.", "speech": "I want to thank Jesus."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-2.svg", "caption": "She cried, wet Jesus' feet with her tears and dried them with her hair.", "speech": "Thank you, Jesus!"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-3.svg", "caption": "Jesus told her that her sins were forgiven and that she could go in peace.", "speech": "What peace in my heart!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-1.svg", "caption": "During a meal at Simon's house, a woman came up to Jesus, crying.", "speech": "I have so much to thank him for."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-2.svg", "caption": "She wet his feet with her tears, dried them with her hair, kissed them and poured perfume on them.", "speech": "Thank you for forgiving me."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-3.svg", "caption": "Simon judged the woman. Jesus told of two men who owed money, and the lender forgave them both.", "speech": "Which of the two will love him more?"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-4.svg", "caption": "Whoever is forgiven more loves more. Jesus told the woman that her sins were forgiven.", "speech": "Go in peace."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '7-10' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/a-mulher-e-o-perfume/quadros/11-13-cena.svg", "setup": "Simon's house; he is a Pharisee. You are one of the guests. A woman known in town as a sinner comes in crying and begins to care for Jesus' feet with tears and perfume. Everyone looks at you.", "question": "What would you think?", "options": ["This is no place for her", "She knows how much she needs forgiveness", "I need to be forgiven too"], "outcome": "Jesus knew what Simon was thinking and told of two debtors who were forgiven. The one forgiven more would have more reason to love. The woman's actions showed gratitude for forgiveness received, and she left in peace.", "quote": "Your sins are forgiven. Go in peace.", "outcomeQuestion": "What would change in the way you see her?", "today": "Those who remember how much they were forgiven tend to forgive and welcome others better. Those who think they owe nothing tend to judge.", "todayQuestion": "When did you last thank God for being forgiven?"}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '11-13' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-1.svg", "caption": "Jesús comía en casa de Simón. Una mujer llegó con un frasco de perfume.", "speech": "Quiero darle las gracias a Jesús."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-2.svg", "caption": "Ella lloró, mojó los pies de Jesús con sus lágrimas y los secó con sus cabellos.", "speech": "¡Gracias, Jesús!"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-3.svg", "caption": "Jesús le dijo que sus pecados estaban perdonados y que podía irse en paz.", "speech": "¡Qué paz en el corazón!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-1.svg", "caption": "Durante una comida en casa de Simón, una mujer se acercó a Jesús llorando.", "speech": "Tengo tanto que agradecerle."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-2.svg", "caption": "Ella mojó sus pies con lágrimas, los secó con sus cabellos, los besó y derramó perfume sobre ellos.", "speech": "Gracias por perdonarme."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-3.svg", "caption": "Simón juzgaba a la mujer. Jesús contó de dos hombres que debían dinero, y el prestamista perdonó a ambos.", "speech": "¿Cuál de los dos lo amará más?"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-4.svg", "caption": "Quien recibe un perdón mayor ama más. Jesús le dijo a la mujer que sus pecados estaban perdonados.", "speech": "Ve en paz."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '7-10' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/a-mulher-e-o-perfume/quadros/11-13-cena.svg", "setup": "La casa de Simón, un fariseo. Eres uno de los invitados. Una mujer conocida en la ciudad como pecadora entra llorando y empieza a cuidar los pies de Jesús con lágrimas y perfume. Todos te miran.", "question": "¿Qué pensarías?", "options": ["Este no es lugar para ella", "Ella sabe cuánto necesita el perdón", "Yo también necesito ser perdonado"], "outcome": "Jesús conocía los pensamientos de Simón y contó de dos deudores perdonados. Quien recibió el perdón mayor tendría más motivos para amar. Los gestos de la mujer mostraban gratitud por un perdón recibido, y ella se fue en paz.", "quote": "Tus pecados te son perdonados. Ve en paz.", "outcomeQuestion": "¿Qué cambiaría en tu manera de verla?", "today": "Quien recuerda cuánto fue perdonado suele perdonar y acoger mejor. Quien se cree sin deuda tiende a juzgar.", "todayQuestion": "¿Cuándo fue la última vez que agradeciste a Dios por haber sido perdonado?"}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '11-13' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-1.svg", "caption": "Jésus mangeait chez Simon. Une femme est arrivée avec un flacon de parfum.", "speech": "Je veux remercier Jésus."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-2.svg", "caption": "Elle a pleuré, mouillé les pieds de Jésus de ses larmes et les a essuyés avec ses cheveux.", "speech": "Merci, Jésus !"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-3.svg", "caption": "Jésus lui a dit que ses péchés étaient pardonnés et qu'elle pouvait partir en paix.", "speech": "Quelle paix dans mon cœur !"}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-1.svg", "caption": "Pendant un repas chez Simon, une femme s'est approchée de Jésus en pleurant.", "speech": "J'ai tant de raisons de le remercier."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-2.svg", "caption": "Elle a mouillé ses pieds de ses larmes, les a essuyés avec ses cheveux, les a embrassés et y a versé du parfum.", "speech": "Merci de m'avoir pardonné."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-3.svg", "caption": "Simon jugeait la femme. Jésus a raconté l'histoire de deux hommes qui devaient de l'argent : le prêteur leur a pardonné à tous les deux.", "speech": "Lequel des deux l'aimera le plus ?"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-4.svg", "caption": "Celui à qui l'on pardonne davantage aime davantage. Jésus a dit à la femme que ses péchés étaient pardonnés.", "speech": "Va en paix."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '7-10' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/a-mulher-e-o-perfume/quadros/11-13-cena.svg", "setup": "La maison de Simon, un pharisien. Tu es l'un des invités. Une femme connue dans la ville comme pécheresse entre en pleurant et se met à prendre soin des pieds de Jésus avec des larmes et du parfum. Tout le monde te regarde.", "question": "Que penserais-tu ?", "options": ["Ce n'est pas sa place ici", "Elle sait combien elle a besoin de pardon", "J'ai moi aussi besoin d'être pardonné"], "outcome": "Jésus connaissait les pensées de Simon et a raconté l'histoire de deux débiteurs pardonnés. Celui à qui l'on avait pardonné davantage aurait plus de raisons d'aimer. Les gestes de la femme montraient sa reconnaissance pour le pardon reçu, et elle est partie en paix.", "quote": "Tes péchés sont pardonnés. Va en paix.", "outcomeQuestion": "Qu'est-ce qui changerait dans ton regard sur elle ?", "today": "Celui qui se souvient de tout ce qui lui a été pardonné pardonne et accueille mieux. Celui qui se croit sans dette a tendance à juger.", "todayQuestion": "Quand as-tu remercié Dieu pour la dernière fois d'avoir été pardonné ?"}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '11-13' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-1.svg", "caption": "Gesù mangiava a casa di Simone. Una donna arrivò con un vasetto di profumo.", "speech": "Voglio ringraziare Gesù."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-2.svg", "caption": "Lei pianse, bagnò i piedi di Gesù con le lacrime e li asciugò con i capelli.", "speech": "Grazie, Gesù!"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/4-6-3.svg", "caption": "Gesù le disse che i suoi peccati erano perdonati e che poteva andare in pace.", "speech": "Che pace nel cuore!"}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-1.svg", "caption": "Durante un pranzo a casa di Simone, una donna si avvicinò a Gesù piangendo.", "speech": "Ho tanto da ringraziare."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-2.svg", "caption": "Bagnò i suoi piedi con le lacrime, li asciugò con i capelli, li baciò e vi versò il profumo.", "speech": "Grazie per avermi perdonata."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-3.svg", "caption": "Simone giudicava la donna. Gesù raccontò di due uomini che avevano un debito, e il creditore li perdonò entrambi.", "speech": "Quale dei due lo amerà di più?"}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/7-10-4.svg", "caption": "Chi riceve un perdono più grande ama di più. Gesù disse alla donna che i suoi peccati erano perdonati.", "speech": "Va' in pace."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '7-10' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/a-mulher-e-o-perfume/quadros/11-13-cena.svg", "setup": "La casa di Simone, un fariseo. Sei uno degli invitati. Una donna conosciuta in città come peccatrice entra piangendo e comincia a prendersi cura dei piedi di Gesù con lacrime e profumo. Tutti guardano te.", "question": "Che cosa penseresti?", "options": ["Questo non è posto per lei", "Lei sa quanto ha bisogno di perdono", "Anch'io ho bisogno di essere perdonato"], "outcome": "Gesù conosceva i pensieri di Simone e raccontò di due debitori perdonati. Chi aveva ricevuto il perdono più grande avrebbe avuto più motivi per amare. I gesti della donna mostravano gratitudine per un perdono ricevuto, ed ella se ne andò in pace.", "quote": "I tuoi peccati sono perdonati. Va' in pace.", "outcomeQuestion": "Che cosa cambierebbe nel tuo modo di guardarla?", "today": "Chi ricorda quanto gli è stato perdonato di solito perdona e accoglie meglio. Chi si crede senza debiti tende a giudicare.", "todayQuestion": "Quando hai ringraziato Dio per l'ultima volta per essere stato perdonato?"}$j$::jsonb
 WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '11-13' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/4-6-1.svg", "caption": "Jesus chegou à casa de Marta, e ela o recebeu.", "speech": "Seja bem-vindo!"}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-2.svg", "caption": "Marta cuidava de tudo. Maria se sentou aos pés de Jesus para ouvir.", "speech": "Quero ouvir você."}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-3.svg", "caption": "Marta pediu ajuda. Jesus disse que Maria tinha feito uma boa escolha e podia ficar ali.", "speech": "Marta, Marta..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/7-10-1.svg", "caption": "Quando Jesus chegou, Marta o recebeu em casa e logo se ocupou com os preparativos.", "speech": "Tem tanta coisa para fazer!"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-2.svg", "caption": "Maria, sua irmã, sentou-se aos pés de Jesus para ouvir seu ensino.", "speech": "Que palavras boas!"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-3.svg", "caption": "Marta, preocupada com muitas coisas, pediu que Jesus mandasse Maria ajudar.", "speech": "Senhor, não te importas?"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-4.svg", "caption": "Jesus chamou Marta pelo nome. Ouvir sua palavra era necessário, e Maria podia continuar ali.", "speech": "Marta, Marta..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '7-10' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/marta-e-maria/quadros/11-13-cena.svg", "setup": "Uma aldeia, a casa de Marta. Você é Marta. Jesus acabou de chegar, e há muito a fazer. Sua irmã Maria se sentou para ouvi-lo, e você está sozinha na cozinha.", "question": "O que você faria?", "options": ["Reclamar com Maria", "Pedir ajuda a Jesus", "Largar tudo e sentar para ouvir"], "outcome": "Marta levou a queixa a Jesus. Ele a chamou pelo nome, falou das muitas preocupações que a deixavam inquieta e disse que Maria tinha escolhido a boa parte. Marta queria oferecer algo a Jesus, e ele a ajudou a ver o que ela também precisava receber.", "quote": "Maria escolheu a boa parte, e ela não lhe será tirada.", "outcomeQuestion": "O que Marta poderia ter feito de diferente?", "today": "Hoje, tarefas, telas e agenda disputam nossa atenção, até para coisas boas. Ouvir Jesus não compete com servir: é o que dá sentido ao serviço.", "todayQuestion": "O que você poderia pausar hoje para ficar um tempo com Jesus?"}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '11-13' AND language = 'pt-BR';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/4-6-1.svg", "caption": "Jesus came to Martha's house, and she welcomed him.", "speech": "Welcome!"}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-2.svg", "caption": "Martha took care of everything. Mary sat at Jesus' feet to listen.", "speech": "I want to hear you."}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-3.svg", "caption": "Martha asked for help. Jesus said Mary had made a good choice and could stay.", "speech": "Martha, Martha..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/7-10-1.svg", "caption": "When Jesus arrived, Martha welcomed him into her home and quickly got busy with the preparations.", "speech": "There is so much to do!"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-2.svg", "caption": "Mary, her sister, sat at Jesus' feet to listen to his teaching.", "speech": "What good words!"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-3.svg", "caption": "Martha, worried about many things, asked Jesus to tell Mary to help.", "speech": "Lord, don't you care?"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-4.svg", "caption": "Jesus called Martha by name. Listening to his word was needed, and Mary could stay right there.", "speech": "Martha, Martha..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '7-10' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/marta-e-maria/quadros/11-13-cena.svg", "setup": "A village, Martha's house. You are Martha. Jesus has just arrived, and there is a lot to do. Your sister Mary sat down to listen to him, and you are alone in the kitchen.", "question": "What would you do?", "options": ["Complain to Mary", "Ask Jesus for help", "Drop everything and sit down to listen"], "outcome": "Martha took her complaint to Jesus. He called her by name, spoke of the many worries that made her restless and said Mary had chosen the good part. Martha wanted to give something to Jesus, and he helped her see what she also needed to receive.", "quote": "Mary has chosen the good part, and it will not be taken from her.", "outcomeQuestion": "What could Martha have done differently?", "today": "Today, tasks, screens and schedules compete for our attention, even for good things. Listening to Jesus doesn't compete with serving: it gives serving its meaning.", "todayQuestion": "What could you pause today to spend some time with Jesus?"}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '11-13' AND language = 'en';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/4-6-1.svg", "caption": "Jesús llegó a la casa de Marta, y ella lo recibió.", "speech": "¡Bienvenido!"}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-2.svg", "caption": "Marta se ocupaba de todo. María se sentó a los pies de Jesús para escuchar.", "speech": "Quiero escucharte."}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-3.svg", "caption": "Marta pidió ayuda. Jesús dijo que María había hecho una buena elección y podía quedarse.", "speech": "Marta, Marta..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/7-10-1.svg", "caption": "Cuando Jesús llegó, Marta lo recibió en su casa y enseguida se ocupó de los preparativos.", "speech": "¡Hay tanto por hacer!"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-2.svg", "caption": "María, su hermana, se sentó a los pies de Jesús para escuchar su enseñanza.", "speech": "¡Qué palabras tan buenas!"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-3.svg", "caption": "Marta, preocupada por muchas cosas, pidió que Jesús le dijera a María que ayudara.", "speech": "Señor, ¿no te importa?"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-4.svg", "caption": "Jesús llamó a Marta por su nombre. Escuchar su palabra era necesario, y María podía seguir allí.", "speech": "Marta, Marta..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '7-10' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/marta-e-maria/quadros/11-13-cena.svg", "setup": "Una aldea, la casa de Marta. Eres Marta. Jesús acaba de llegar y hay mucho por hacer. Tu hermana María se sentó a escucharlo, y tú estás sola en la cocina.", "question": "¿Qué harías?", "options": ["Quejarme con María", "Pedirle ayuda a Jesús", "Dejarlo todo y sentarme a escuchar"], "outcome": "Marta llevó su queja a Jesús. Él la llamó por su nombre, habló de las muchas preocupaciones que la tenían inquieta y dijo que María había elegido la buena parte. Marta quería ofrecer algo a Jesús, y él la ayudó a ver lo que ella también necesitaba recibir.", "quote": "María escogió la buena parte, y no le será quitada.", "outcomeQuestion": "¿Qué podría haber hecho Marta de otra manera?", "today": "Hoy, las tareas, las pantallas y la agenda compiten por nuestra atención, incluso para cosas buenas. Escuchar a Jesús no compite con servir: es lo que da sentido al servicio.", "todayQuestion": "¿Qué podrías pausar hoy para pasar un tiempo con Jesús?"}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '11-13' AND language = 'es';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/4-6-1.svg", "caption": "Jésus est arrivé chez Marthe, et elle l'a accueilli.", "speech": "Sois le bienvenu !"}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-2.svg", "caption": "Marthe s'occupait de tout. Marie s'est assise aux pieds de Jésus pour écouter.", "speech": "Je veux t'écouter."}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-3.svg", "caption": "Marthe a demandé de l'aide. Jésus a dit que Marie avait fait un bon choix et qu'elle pouvait rester.", "speech": "Marthe, Marthe..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/7-10-1.svg", "caption": "Quand Jésus est arrivé, Marthe l'a accueilli chez elle et s'est vite affairée aux préparatifs.", "speech": "Il y a tant à faire !"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-2.svg", "caption": "Marie, sa sœur, s'est assise aux pieds de Jésus pour écouter son enseignement.", "speech": "Quelles belles paroles !"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-3.svg", "caption": "Marthe, préoccupée par beaucoup de choses, a demandé à Jésus de dire à Marie de l'aider.", "speech": "Seigneur, cela ne te fait rien ?"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-4.svg", "caption": "Jésus a appelé Marthe par son nom. Écouter sa parole était nécessaire, et Marie pouvait rester là.", "speech": "Marthe, Marthe..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '7-10' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/marta-e-maria/quadros/11-13-cena.svg", "setup": "Un village, la maison de Marthe. Tu es Marthe. Jésus vient d'arriver, et il y a beaucoup à faire. Ta sœur Marie s'est assise pour l'écouter, et tu es seule dans la cuisine.", "question": "Que ferais-tu ?", "options": ["Me plaindre à Marie", "Demander de l'aide à Jésus", "Tout laisser et m'asseoir pour écouter"], "outcome": "Marthe a porté sa plainte à Jésus. Il l'a appelée par son nom, a parlé des nombreux soucis qui l'agitaient et a dit que Marie avait choisi la bonne part. Marthe voulait offrir quelque chose à Jésus, et il l'a aidée à voir ce qu'elle avait elle aussi besoin de recevoir.", "quote": "Marie a choisi la bonne part, qui ne lui sera pas enlevée.", "outcomeQuestion": "Qu'est-ce que Marthe aurait pu faire autrement ?", "today": "Aujourd'hui, les tâches, les écrans et l'agenda se disputent notre attention, même pour de bonnes choses. Écouter Jésus ne s'oppose pas à servir : c'est ce qui donne un sens au service.", "todayQuestion": "Qu'est-ce que tu pourrais mettre en pause aujourd'hui pour passer un moment avec Jésus ?"}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '11-13' AND language = 'fr';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/4-6-1.svg", "caption": "Gesù arrivò a casa di Marta, e lei lo accolse.", "speech": "Benvenuto!"}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-2.svg", "caption": "Marta si occupava di tutto. Maria si sedette ai piedi di Gesù per ascoltare.", "speech": "Voglio ascoltarti."}, {"image": "/ilustracoes/marta-e-maria/quadros/4-6-3.svg", "caption": "Marta chiese aiuto. Gesù disse che Maria aveva fatto una buona scelta e poteva restare lì.", "speech": "Marta, Marta..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "panels", "panels": [{"image": "/ilustracoes/marta-e-maria/quadros/7-10-1.svg", "caption": "Quando Gesù arrivò, Marta lo accolse in casa e si mise subito a fare i preparativi.", "speech": "C'è tanto da fare!"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-2.svg", "caption": "Maria, sua sorella, si sedette ai piedi di Gesù per ascoltare il suo insegnamento.", "speech": "Che belle parole!"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-3.svg", "caption": "Marta, preoccupata per molte cose, chiese a Gesù di dire a Maria di aiutarla.", "speech": "Signore, non t'importa?"}, {"image": "/ilustracoes/marta-e-maria/quadros/7-10-4.svg", "caption": "Gesù chiamò Marta per nome. Ascoltare la sua parola era necessario, e Maria poteva restare lì.", "speech": "Marta, Marta..."}]}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '7-10' AND language = 'it';

UPDATE devotional_kids SET story = $j${"format": "dilemma", "image": "/ilustracoes/marta-e-maria/quadros/11-13-cena.svg", "setup": "Un villaggio, la casa di Marta. Sei Marta. Gesù è appena arrivato e c'è molto da fare. Tua sorella Maria si è seduta ad ascoltarlo, e tu sei sola in cucina.", "question": "Che cosa faresti?", "options": ["Lamentarmi con Maria", "Chiedere aiuto a Gesù", "Lasciare tutto e sedermi ad ascoltare"], "outcome": "Marta portò la sua lamentela a Gesù. Lui la chiamò per nome, parlò delle molte preoccupazioni che la agitavano e disse che Maria aveva scelto la parte buona. Marta voleva offrire qualcosa a Gesù, e lui la aiutò a vedere ciò che anche lei aveva bisogno di ricevere.", "quote": "Maria ha scelto la parte buona, che non le sarà tolta.", "outcomeQuestion": "Che cosa avrebbe potuto fare Marta di diverso?", "today": "Oggi compiti, schermi e agenda si contendono la nostra attenzione, anche per cose buone. Ascoltare Gesù non è in concorrenza con il servire: è ciò che dà senso al servizio.", "todayQuestion": "Che cosa potresti mettere in pausa oggi per stare un po' con Gesù?"}$j$::jsonb
 WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '11-13' AND language = 'it';

SELECT d.publication_date, k.language, k.band, k.story->>'format' AS formato, jsonb_array_length(k.story->'panels') AS quadros
  FROM devotional_kids k JOIN devotionals d ON d.id = k.devotional_id
 WHERE k.devotional_id IN ('cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvyun7rw0032o72lmlzc68bk','cmvyv3ozp003ho72lezbf5h9r') AND k.story IS NOT NULL ORDER BY d.publication_date, k.language, k.band;

DO $$
BEGIN
  IF (SELECT count(*) FROM devotional_kids WHERE devotional_id IN ('cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvyun7rw0032o72lmlzc68bk','cmvyv3ozp003ho72lezbf5h9r') AND language IN ('pt-BR','en','es','fr','it') AND story IS NOT NULL) <> 60 THEN
    RAISE EXCEPTION 'Os UPDATEs não atingiram as 60 versões; desfazendo.';
  END IF;
END $$;

COMMIT;
